INSERT INTO Rod (Rod_ID, Book_ID, Rod_Name, Rod_Description, Rod_Caster_Level, Rod_Cost, Rod_Aura, Rod_Creation_Reqs) VALUES
    (38,4,"Rod of Sand Repelling",
        "<p>This clear glass rod forces sand, dust, ash, grit, and similar loose soils away in a 10-foot-radius sphere. This ability functions on command. The user can travel through sand and loose soil as the rod pushes the material away. Breathing is not a problem as long as the surrounding area is not poisonous or a vacuum. It cannot keep duststorms at bay, but it does protect against any of the effects of the suspended grit in the storm (such as nonlethal damage and potential suffocation).</p>",
        15,60000.00,"Strong abjuration",
        "CL 15th; Craft Rod, wind wall");

INSERT INTO Staff (Staff_ID, Book_ID, Staff_Name, Staff_Description, Staff_Caster_Level, Staff_Cost, Staff_Aura, Staff_Creation_Reqs) VALUES
    (23,4,"Staff of Nomads",
        "<p>A simple, wooden staff with a pronounced bend at the top, this item appears to be nothing more than a shepherd's crook. It allows the use of the following spells:</p><p><ul><li><em>Cloak of shade</em> (1 charge)</li><li><em>Locate water</em> (1 charge)</li><li><em>Hydrate</em> (1 charge)</li><li><em>Find the path</em> (2 charges)</li></ul></p>",
        12,49500.00,"Strong divination",
        "CL 12th; Craft Staff, find the path, cloak of shade, locate water, hydrate"),

    (24,4,"Staff of The Pharaoh",
        "<p>This staff is covered in gold leaf, giving it a metallic sheen. The head forms a large hook, open in the center. It allows the use of the following spells:</p><p><ul><li><em>Cause fear</em> (1 charge)</li><li><em>Summon monster IV</em> (a celestial or fiendish snake, Huge viper only) (1 charge)</li><li><em>Lightning bolt</em> (1 charge)</li><li><em>Control weather</em> (2 charges)</li></ul></p>",
        13,82901.00,"Strong transmutation",
        "CL 13th; Craft Staff, cause fear, control weather, lightning bolt, summon monster IV"),

    (25,4,"Staff of The Sands",
        "<p>A clear glass sphere half filled with dust tops this staff of fused and vitreus sand. It allows use of the following spells:</p><p><ul><li><em>Blast of sand</em> (1 charge)</li><li><em>Haboob</em> (1 charge)</li><li><em>Flaywind burst</em> (2 charges)</li><li><em>Sandstorm</em> (2 charges)</li></ul></p>",
        12,79890.00,"Strong conjuration",
        "CL 12th; Craft Staff, sandstorm, flaywind burst, blast of sand, haboob"),

    (26,4,"Staff of Withering Thirst",
        "<p>This horrid staff is crafted from the mummified limb of a creature that died of thirst. It allows use of the following spells:</p><p><ul><li><em>Desiccate</em> (1 charge)</li><li><em>Wither</em> (2 charges)</li><li><em>Dispel water</em> (2 charges)</li><li><em>Mass desiccate</em> (2 charges)</li><li><em>Horrid wilting</em> (3 charges)</li></ul></p>",
        15,91880.00,"Strong necromancy and abjuration",
        "CL 15th; Craft Staff, desiccate, dispel water, horrid wilting, mass desiccate, wither");